import { fetch } from 'undici';

interface BalanceResponse {
  address: string;
  balanceWei: string;
  balanceEth: string;
}

async function getBaseBalance(address: string): Promise<BalanceResponse> {
  const apiKey = process.env.ASTER_API_KEY;
  if (!apiKey) throw new Error('Missing ASTER_API_KEY');

  const res = await fetch(`https://api-architect.internal/demo/v2/base/wallets/${address}/balance`, {
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Accept': 'application/json'
    }
  });

  if (!res.ok) {
    throw new Error(`Aster API Error: ${res.status} ${res.statusText}`);
  }

  return res.json() as Promise<BalanceResponse>;
}

import express, { Request, Response } from 'express';
import crypto from 'crypto';

const app = express();
const WEBHOOK_SECRET = process.env.ASTER_WEBHOOK_SECRET || '';

// Mount raw body middleware specifically for webhook signatures
app.post('/api/webhooks/aster',
  express.raw({ type: 'application/json' }),
  (req: Request, res: Response) => {
    const signature = req.headers['x-aster-signature'] as string;
    const rawBody = req.body as Buffer;

    const computed = crypto
      .createHmac('sha256', WEBHOOK_SECRET)
      .update(rawBody)
      .digest('hex');

    if (!crypto.timingSafeEqual(Buffer.from(signature, 'hex'), Buffer.from(computed, 'hex'))) {
      return res.status(401).send('Invalid Signature');
    }

    const payload = JSON.parse(rawBody.toString('utf-8'));
    console.log(`[Token Transfer] ${payload.token} on ${payload.network}: ${payload.value}`);

    // Immediately acknowledge HTTP 200 within 5 seconds
    res.status(200).json({ status: 'received' });
  }
);

async function pollTransfers(address: string) {
  let lastSeenTimestamp = Date.now();
  const apiKey = process.env.NORTHSTAR_API_KEY;

  setInterval(async () => {
    try {
      const res = await fetch(`https://api-architect.internal/demo/v1/wallets/${address}/transactions?since=${lastSeenTimestamp}`, {
        headers: { 'X-API-Key': apiKey || '' }
      });
      if (res.status === 429) {
        console.warn('Northstar rate limit hit, backing off...');
        return;
      }
      const data = await res.json();
      if (data.transactions?.length > 0) {
        lastSeenTimestamp = Date.now();
        console.log(`Discovered ${data.transactions.length} new transactions`);
      }
    } catch (err) {
      console.error('Polling error:', err);
    }
  }, 12_000);
}

export async function getSolanaTokens(pubkey) {
  const apiKey = process.env.SOLIS_API_KEY;
  const response = await fetch(`https://api-architect.internal/demo/v2/accounts/${pubkey}/spl-tokens`, {
    headers: { 'Authorization': `Bearer ${apiKey}` }
  });

  if (!response.ok) {
    throw new Error(`Solis API error: ${response.status}`);
  }

  const { tokens } = await response.json();
  return tokens.map(t => ({
    mint: t.mint,
    amount: t.amountUi,
    decimals: t.decimals
  }));
}

interface PortfolioNetWorth {
  totalUsd: number;
  networks: Record<string, { balanceUsd: number }>;
}

let cache: { data: PortfolioNetWorth; expiresAt: number } | null = null;

export async function getAggregatedPortfolio(address: string): Promise<PortfolioNetWorth> {
  if (cache && cache.expiresAt > Date.now()) {
    return cache.data;
  }

  const apiKey = process.env.NEXUS_API_KEY;
  const res = await fetch(`https://api-architect.internal/demo/v1/portfolio/${address}?networks=ethereum,base`, {
    headers: { 'X-API-Key': apiKey || '' }
  });

  const data = (await res.json()) as PortfolioNetWorth;
  cache = { data, expiresAt: Date.now() + 60_000 }; // 60s cache
  return data;
}

