def verify_settlement(tx_hash: str):
    key = os.environ.get('STRATA_API_KEY')
    res = requests.get(
        f"https://api-architect.internal/demo/v1/settlements/{tx_hash}",
        headers={"X-API-Key": key}
    )
    data = res.json()
    return data.get('status') == 'FINALIZED' and data.get('confirmations', 0) >= 32

